def parse_ports(lines):
    result = []
    for line in lines:
        parts = line.split()
        if len(parts) >= 2:
            protocol = parts[0]
            port_str = parts[1]
            if protocol == 'tcp' and port_str == 'open':
                result.append(int(port_str))
    return sorted(result)

